import"./chunk-ZW5NV4UO.js";var o={uk:{title:"\u041A\u0443\u043B\u044C\u0442\u0443\u0440\u0430 \u0442\u0430 \u0437\u0430\u0445\u043E\u043F\u043B\u0435\u043D\u043D\u044F \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u043E\u044E \u043D\u0430 Mastodon",description:"\u041C\u0430\u043B\u044E\u0432\u0430\u043D\u043D\u044F, \u0440\u0443\u043A\u043E\u0434\u0456\u043B\u043B\u044F, \u043A\u043D\u0438\u0436\u043A\u0438, \u0444\u043E\u0442\u043E\u0433\u0440\u0430\u0444\u0456\u044F, \u0456\u0433\u0440\u0438 \u0442\u0430 \u0440\u043E\u0437\u043C\u043E\u0432\u043D\u0456 \u043A\u043B\u0443\u0431\u0438: \u0443\u043A\u0440\u0430\u0457\u043D\u043E\u043C\u043E\u0432\u043D\u0456 \u0441\u043F\u0456\u043B\u044C\u043D\u043E\u0442\u0438 \u043D\u0430 Mastodon.",heading:"\u041A\u0443\u043B\u044C\u0442\u0443\u0440\u0430 \u0442\u0430 \u0437\u0430\u0445\u043E\u043F\u043B\u0435\u043D\u043D\u044F \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u043E\u044E \u043D\u0430 Mastodon",listTitle:"\u041A\u0443\u043B\u044C\u0442\u0443\u0440\u0430 \u0442\u0430 \u0437\u0430\u0445\u043E\u043F\u043B\u0435\u043D\u043D\u044F \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u043E\u044E",intro:["\u041C\u0430\u043B\u044E\u0432\u0430\u043D\u043D\u044F, \u043C\u2019\u044F\u043A\u0456 \u0456\u0433\u0440\u0430\u0448\u043A\u0438 \u0440\u0443\u0447\u043D\u043E\u0457 \u0440\u043E\u0431\u043E\u0442\u0438, \u043A\u043D\u0438\u0436\u043A\u0438, \u043F\u0440\u043E\u0433\u0443\u043B\u044F\u043D\u043A\u0438 \u0437 \u043A\u0430\u043C\u0435\u0440\u043E\u044E, \u0456\u0433\u0440\u0438 \u0442\u0430 \u0440\u043E\u0437\u043C\u043E\u0432\u043D\u0456 \u043A\u043B\u0443\u0431\u0438. \u0422\u0443\u0442 \u0454 \u043D\u0435\u0432\u0435\u043B\u0438\u043A\u0456 \u0442\u0432\u043E\u0440\u0447\u0456 \u0441\u043F\u0456\u043B\u044C\u043D\u043E\u0442\u0438 \u0439 \u0430\u0432\u0442\u043E\u0440\u0438, \u044F\u043A\u0456 \u0434\u0456\u043B\u044F\u0442\u044C\u0441\u044F \u0441\u0432\u043E\u0457\u043C\u0438 \u0437\u0430\u0445\u043E\u043F\u043B\u0435\u043D\u043D\u044F\u043C\u0438 \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u043E\u044E. \u041C\u0456\u0441\u0446\u0435 \u043F\u0440\u043E\u0436\u0438\u0432\u0430\u043D\u043D\u044F \u043D\u0435 \u043C\u0430\u0454 \u0437\u043D\u0430\u0447\u0435\u043D\u043D\u044F; \u0443 \u0437\u043C\u0456\u0448\u0430\u043D\u0438\u0445 \u0441\u0442\u0440\u0456\u0447\u043A\u0430\u0445 \u0442\u0440\u0430\u043F\u043B\u044F\u044E\u0442\u044C\u0441\u044F \u0439 \u0456\u043D\u0448\u0456 \u043C\u043E\u0432\u0438.","\u0426\u0435 \u043D\u0435\u0432\u0435\u043B\u0438\u043A\u0430 \u0434\u043E\u0431\u0456\u0440\u043A\u0430 \u0437 \u0440\u0456\u0437\u043D\u0438\u043C \u0442\u0435\u043C\u043F\u043E\u043C \u043F\u0443\u0431\u043B\u0456\u043A\u0430\u0446\u0456\u0439. \u0427\u0430\u0441\u0442\u0438\u043D\u0430 \u0430\u0432\u0442\u043E\u0440\u0456\u0432 \u043F\u0438\u0448\u0435 \u0440\u0456\u0434\u043A\u043E: \u0434\u043B\u044F \u0446\u0456\u0454\u0457 \u043C\u043E\u0432\u043D\u043E\u0457 \u0441\u043F\u0456\u043B\u044C\u043D\u043E\u0442\u0438 \u0432\u0440\u0430\u0445\u043E\u0432\u0443\u0454\u043C\u043E \u0430\u043A\u0442\u0438\u0432\u043D\u0456\u0441\u0442\u044C \u0437\u0430 \u043E\u0441\u0442\u0430\u043D\u043D\u0456 30 \u043C\u0456\u0441\u044F\u0446\u0456\u0432. \u041F\u043E\u0440\u044F\u0434 \u0456\u0437 \u0442\u0432\u043E\u0440\u0447\u0456\u0441\u0442\u044E \u043C\u043E\u0436\u0443\u0442\u044C \u0431\u0443\u0442\u0438 \u043E\u0441\u043E\u0431\u0438\u0441\u0442\u0456 \u0434\u043E\u043F\u0438\u0441\u0438, \u043F\u0440\u043E\u0434\u0430\u0436 \u0432\u043B\u0430\u0441\u043D\u0438\u0445 \u0432\u0438\u0440\u043E\u0431\u0456\u0432, \u0431\u043B\u0430\u0433\u043E\u0434\u0456\u0439\u043D\u0456 \u0437\u0431\u043E\u0440\u0438 \u0439 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442 \u0432\u0456\u0439\u043D\u0438. \u041F\u0435\u0440\u0435\u0433\u043B\u044F\u043D\u044C \u043F\u0440\u043E\u0444\u0456\u043B\u0456 \u0442\u0430 \u043E\u0431\u0435\u0440\u0438 \u0442\u0435, \u0449\u043E \u0442\u043E\u0431\u0456 \u0446\u0456\u043A\u0430\u0432\u043E.","\u0426\u044F \u0434\u043E\u0431\u0456\u0440\u043A\u0430 \u043C\u0456\u0441\u0442\u0438\u0442\u044C \u043B\u0438\u0448\u0435 \u0430\u043A\u0430\u0443\u043D\u0442\u0438. \u0425\u0435\u0448\u0442\u0435\u0433\u0438 \u043D\u0435 \u0440\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0443\u0454\u043C\u043E: \u043F\u0435\u0440\u0435\u0432\u0456\u0440\u0435\u043D\u0456 \u043F\u043E\u0442\u043E\u043A\u0438 \u0431\u0443\u043B\u0438 \u043D\u0435\u0430\u043A\u0442\u0438\u0432\u043D\u0438\u043C\u0438, \u043D\u0430\u0434\u0442\u043E \u0437\u0430\u0433\u0430\u043B\u044C\u043D\u0438\u043C\u0438 \u0430\u0431\u043E \u043C\u0456\u0441\u0442\u0438\u043B\u0438 \u0431\u0430\u0433\u0430\u0442\u043E \u0434\u043E\u043F\u0438\u0441\u0456\u0432 \u0456\u043D\u0448\u0438\u043C\u0438 \u043C\u043E\u0432\u0430\u043C\u0438."],faq:[{q:"\u0427\u0438 \u043F\u043E\u0442\u0440\u0456\u0431\u0435\u043D \u0430\u043A\u0430\u0443\u043D\u0442?",a:"\u041D\u0456, \u0449\u043E\u0431 \u043F\u0435\u0440\u0435\u0433\u043B\u044F\u0434\u0430\u0442\u0438 \u043F\u0440\u043E\u0444\u0456\u043B\u0456 \u0439 \u043F\u0443\u0431\u043B\u0456\u0447\u043D\u0456 \u0434\u043E\u043F\u0438\u0441\u0438. \u0423\u0432\u0456\u0439\u0434\u0438 \u0447\u0435\u0440\u0435\u0437 Mastodon, \u0449\u043E\u0431 \u043F\u0456\u0434\u043F\u0438\u0441\u0430\u0442\u0438\u0441\u044F \u043D\u0430 \u0430\u0432\u0442\u043E\u0440\u0456\u0432 \u0430\u0431\u043E \u0441\u0442\u0432\u043E\u0440\u0438\u0442\u0438 \u0441\u043F\u0438\u0441\u043E\u043A."},{q:"\u0427\u0438 \u0432\u0441\u0456 \u0434\u043E\u043F\u0438\u0441\u0438 \u0431\u0443\u0434\u0443\u0442\u044C \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u043E\u044E?",a:"\u0410\u0432\u0442\u043E\u0440\u0438 \u0440\u0435\u0433\u0443\u043B\u044F\u0440\u043D\u043E \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u044E\u0442\u044C \u0443\u043A\u0440\u0430\u0457\u043D\u0441\u044C\u043A\u0443, \u0430\u043B\u0435 \u0434\u0435\u044F\u043A\u0456 \u0442\u0430\u043A\u043E\u0436 \u043F\u0438\u0448\u0443\u0442\u044C \u0430\u0431\u043E \u043F\u043E\u0448\u0438\u0440\u044E\u044E\u0442\u044C \u0434\u043E\u043F\u0438\u0441\u0438 \u0456\u043D\u0448\u0438\u043C\u0438 \u043C\u043E\u0432\u0430\u043C\u0438. \u0422\u0443\u0442 \u0454 \u043B\u044E\u0434\u0438 \u0437 \u0423\u043A\u0440\u0430\u0457\u043D\u0438 \u0442\u0430 \u0437-\u0437\u0430 \u043A\u043E\u0440\u0434\u043E\u043D\u0443. \u0414\u043E\u0431\u0456\u0440\u043A\u0430 \u043D\u0435 \u0433\u0430\u0440\u0430\u043D\u0442\u0443\u0454 \u0442\u0435\u043C\u0438 \u0447\u0438 \u043C\u043E\u0432\u0438 \u043A\u043E\u0436\u043D\u043E\u0433\u043E \u043C\u0430\u0439\u0431\u0443\u0442\u043D\u044C\u043E\u0433\u043E \u0434\u043E\u043F\u0438\u0441\u0443."},{q:"\u042F\u043A \u043F\u043E\u0442\u0440\u0430\u043F\u0438\u0442\u0438 \u0434\u043E \u0434\u043E\u0431\u0456\u0440\u043A\u0438 \u0430\u0431\u043E \u043F\u0440\u0438\u0431\u0440\u0430\u0442\u0438 \u0441\u0432\u0456\u0439 \u0430\u043A\u0430\u0443\u043D\u0442?",a:"\u041D\u0430\u043F\u0438\u0448\u0438 @mawkingbird@mastodon.social. \u041D\u0435\u0432\u0435\u043B\u0438\u043A\u0456 \u0442\u0435\u043C\u0430\u0442\u0438\u0447\u043D\u0456 \u0430\u043A\u0430\u0443\u043D\u0442\u0438 \u0442\u0430\u043A\u043E\u0436 \u043C\u043E\u0436\u0443\u0442\u044C \u0431\u0443\u0442\u0438 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u0456, \u044F\u043A\u0449\u043E \u0432\u043E\u043D\u0438 \u0434\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0442\u044C \u043F\u043E\u0448\u0443\u043A \u043F\u0440\u043E\u0444\u0456\u043B\u044E. \u041C\u0438 \u043F\u043E\u0432\u0430\u0436\u0430\u0454\u043C\u043E \u0437\u0430\u0431\u043E\u0440\u043E\u043D\u0443 \u0432\u0435\u0431\u0456\u043D\u0434\u0435\u043A\u0441\u0430\u0446\u0456\u0457 \u0442\u0430 \u043F\u0440\u043E\u0445\u0430\u043D\u043D\u044F \u043F\u0440\u043E \u0432\u0438\u0434\u0430\u043B\u0435\u043D\u043D\u044F."}]}};export{o as COPY};
